// spec: specs/placement-reading.md (2.2, 2.3) · кейсы PRD-08, PRD-03, PRD-06 · запасной путь (повторный вход в новом окне)
// seed: tests/seed.parent.spec.ts
// Общий ребёнок на оба теста → serial. Повторный вход — новое окно с другой сессией (parent ↔ parent-3):
// refresh-токен Supabase одноразовый, одну сессию в двух открытых окнах не держим — предыдущее окно закрывается.
import { BrowserContext, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  answerOnePassage,
  childUrl,
  createChild,
  handoverToIntro,
  openSharedUserPage,
  qaChildName,
  readingScreens,
} from './reading.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

test.describe('Стартовый тест чтения — одна попытка, продолжение, сбои, 390 (autotest-writer)', () => {
  const childName = qaChildName();
  let childId = '';
  // Окно повторного входа из 2.2 — живёт до шага 2 теста 2.3.
  let shared: { context: BrowserContext; page: Page } | undefined;

  test.afterAll(async () => {
    await shared?.context.close();
  });

  test('«אחר כך» на объяснении ведёт домой, при повторном входе снова объяснение @desktop @data #8bf5a8', async ({ browser }, testInfo) => {
    // 1. Окно parent: создать ребёнка, передать устройство → C1
    const first = await openSharedUserPage(browser, testInfo, 'parent');
    try {
      childId = await createChild(first.page, childName, '2018');
      annotateCleanup(testInfo, childName, childId);
      await handoverToIntro(first.page, childId, childName);

      // 2. «אחר כך» → дом ребёнка (AC5 «פעולה בטוחה הבאה»; FL-04 шаг 1)
      await readingScreens(first.page).later.click();
      await first.page.waitForURL(childUrl(childId, 'home'));
    } finally {
      // 3. Закрыть окно ребёнка
      await first.context.close();
    }

    // 3. Окно parent-3: повторный вход через передачу устройства → снова C1, тест не начат (AC2)
    shared = await openSharedUserPage(browser, testInfo, 'parent-3');
    const s = readingScreens(shared.page);
    await handoverToIntro(shared.page, childId, childName);
    await expect(s.introTitle).toBeVisible();
    await expect(s.introCaption).toBeVisible();
    await expect(s.start).toBeVisible();
  });

  test('Частичный прогресс: ответ на отрывок 1, «השהיה», повторный вход → «ממשיכים!» → «קטע 2», после обновления остаётся «קטע 2»; /assessment/writing в процессе ведёт домой @desktop @data #8bf5a8', async ({ browser }, testInfo) => {
    test.setTimeout(3 * 60_000);
    expect(shared, 'нет окна из предыдущего теста (2.2)').toBeDefined();
    expect(childId, 'нет ребёнка из предыдущего теста (2.2)').not.toBe('');
    annotateCleanup(testInfo, childName, childId);

    // 1. В окне из 2.2: «מתחילים!» → «קטע 1» → ответ самооценкой → «קטע 2»
    {
      const page = shared!.page;
      const s = readingScreens(page);
      await s.start.click();
      await expect(s.readingHeader).toBeVisible();
      await expect(s.passage(1)).toBeVisible();
      await answerOnePassage(page, 'בסדר');
      await expect(s.passage(2)).toBeVisible();

      // 2. «השהיה» → дом ребёнка (AC2 «אפשר … לצאת»)
      await s.pause.click();
      await page.waitForURL(childUrl(childId, 'home'));
    }

    // 3. Закрыть окно; новое окно parent: повторный вход
    await shared!.context.close();
    shared = undefined;
    const again = await openSharedUserPage(browser, testInfo, 'parent');
    try {
      const page = again.page;
      const s = readingScreens(page);
      await handoverToIntro(page, childId, childName);

      // C1 «באמצע • ממשיכים מאיפה שעצרנו» и главная кнопка «ממשיכים!» (AC2)
      await expect(page.getByText(/באמצע\s*[•·]\s*ממשיכים מאיפה שעצרנו/)).toBeVisible();
      await expect(s.resume).toBeVisible();

      // 4. «ממשיכים!» → «מבדק התאמה • קריאה», «קטע 2», не «קטע 1» (AC2; F-08)
      await s.resume.click();
      await expect(s.readingHeader).toBeVisible();
      await expect(s.passage(2)).toBeVisible();
      await expect(s.passage(1)).toBeHidden();

      // 5. Обновить — по-прежнему «קטע 2» (G1 «recovery מחזיר לנקודה בטוחה»)
      await page.reload();
      await expect(s.passage(2)).toBeVisible();
      await expect(s.passage(1)).toBeHidden();

      // 6. /assessment/writing у ребёнка в процессе → дом (#be58fd)
      await page.goto(`/${childId}/assessment/writing`);
      await page.waitForURL(childUrl(childId, 'home'));
      await expect(page.getByTestId('writing-input')).toHaveCount(0);
    } finally {
      await again.context.close();
    }
  });
});
